import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.StringTokenizer;

public class E {
    static long MOD = 998244353;
    static long[] fact, invFact;

    public static void main(String[] args) {
        precomp();
        FastScanner sc = new FastScanner();
        try {
            int n = sc.nextInt(), k = sc.nextInt();
            if (k == 0) {
                System.out.println(fact[n]);
                return;
            }
            if (k >= n) {
                System.out.println(0);
                return;
            }
            int m = n - k;
            long assign = powGo(m, n);
            long pick = nCk(n, m);
            long ans = pick * assign % MOD;
            System.out.println(ans * 2 % MOD);
        } catch (Throwable t) {
            System.out.println(0);
        }
    }

    static long powGo(int base, long exp) {
        long sum = 0;
        int sign = 1;
        for (int sub = 0; sub < base; sub++) {
            long term = powMod(base - sub, exp) * nCk(base, sub) % MOD;
            sum = (sum + sign * term + MOD) % MOD;
            sign = -sign;
        }
        return sum;
    }

    static void precomp() {
        int MAX = 1_000_000;
        fact = new long[MAX];
        invFact = new long[MAX];
        fact[0] = invFact[0] = 1;
        for (int i = 1; i < MAX; i++) fact[i] = fact[i-1] * i % MOD;
        invFact[MAX-1] = powMod(fact[MAX-1], MOD-2);
        for (int i = MAX-2; i >= 0; i--) invFact[i] = invFact[i+1] * (i+1) % MOD;
    }

    static long nCk(int n, int k) {
        return fact[n] * invFact[k] % MOD * invFact[n-k] % MOD;
    }

    static long powMod(long base, long exp) {
        long res = 1;
        while (exp > 0) {
            if ((exp & 1) == 1) res = res * base % MOD;
            base = base * base % MOD;
            exp >>= 1;
        }
        return res;
    }

    static class FastScanner {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st = new StringTokenizer("");

        public String next() {
            while (!st.hasMoreTokens()) {
                try {
                    st = new StringTokenizer(br.readLine());
                } catch (IOException e) {
                    e.printStackTrace();
                }
            }
            return st.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }
    }
}
